const input = $input.first().json || {};
const raw = String(input.chatInput ?? input.message ?? '').trim();
const sessionId = String(input.sessionId ?? input.session_id ?? '').trim();
const meta = (input.metadata && typeof input.metadata === 'object') ? input.metadata : {};
const explicitTest = input.spm_test_mode === true || meta.spm_test_mode === true;
const syntheticPrefix = /^(test_|wu87_|synthetic_)/i.test(sessionId);
const testMode = Boolean(explicitTest || syntheticPrefix);
const now = new Date().toISOString();
const correlationId = String(input.correlation_id ?? `wu87-${Date.now()}-${Math.random().toString(36).slice(2,10)}`);
const safeSession = sessionId || `anonymous-${correlationId}`;
return [{json:{
  schema_version:'SPM_E2E_V1',
  workflow_release:'WU87_GREENFIELD_SKELETON',
  workflow_mode:'TEST_ONLY',
  correlation_id:correlationId,
  session_id:safeSession,
  sales_state_key:`spm:sales:${safeSession}`,
  received_at:now,
  started_ms:Date.now(),
  test_mode:testMode,
  synthetic_session:syntheticPrefix,
  channel:'website_chat',
  language_hint:String(input.language ?? input.locale ?? meta.language ?? '').toLowerCase() || null,
  message:{raw, length:raw.length},
  client_context:{origin:meta.origin ?? null},
  contract_status:'SESSION_ENVELOPE_OK'
}}];

const j = $input.first().json || {};
const defaults = {
  schema_version:'SPM_SALES_STATE_V1',
  session_id:j.session_id,
  lead_id:null,
  preferred_language:j.language_hint,
  journey:{stage:'discovery',previous_stage:null,next_best_action:'understand_need',override:null},
  classifier:{spm_intent:null,secondary_spm_intent:null,confidence:0,threshold:0.85,ambiguous:true,source_gate:null,risk_tier:null,sales_stage:null},
  entities:{global:{},students:[]},
  commercial:{package:null,currency:null,authorized_offer:false},
  trial:{status:'not_started'},
  scheduling:{timezone:null,availability_checked:false,booking_status:'not_started',booking_id:null},
  conversion:{registration_status:'not_started',consent:false,lead_write_status:'not_started'},
  support:{handoff_requested:false,handoff_status:'not_started',complaint:false},
  nurture:{opt_out:false,follow_up_eligible:false},
  recovery:{state:null,last_error_code:null},
  flags:{test_mode:Boolean(j.test_mode),synthetic_session:Boolean(j.synthetic_session)},
  updated_at:new Date().toISOString()
};
function merge(base, extra){
  if (!extra || typeof extra !== 'object' || Array.isArray(extra)) return base;
  const out={...base};
  for (const [k,v] of Object.entries(extra)) {
    if (v === undefined) continue;
    if (v && typeof v === 'object' && !Array.isArray(v) && base[k] && typeof base[k] === 'object' && !Array.isArray(base[k])) out[k]=merge(base[k],v);
    else out[k]=v;
  }
  return out;
}
let existing={};
if (j.sales_state_raw) {
  try { existing = typeof j.sales_state_raw === 'string' ? JSON.parse(j.sales_state_raw) : j.sales_state_raw; } catch { existing={}; }
}
const state=merge(defaults,existing);
state.session_id=j.session_id;
state.flags={...(state.flags||{}),test_mode:Boolean(j.test_mode),synthetic_session:Boolean(j.synthetic_session)};
state.updated_at=new Date().toISOString();
return [{json:{...j,sales_state:state,sales_state_contract:'SPM_SALES_STATE_V1',state_merge_mode:'NON_DESTRUCTIVE'}}];

const j=$input.first().json;
const contract={
  schema:'SPM_CLASSIFIER_OUTPUT_V1',
  required:['spm_intent','confidence','threshold','ambiguous','source_gate','risk_tier','sales_stage'],
  optional:['secondary_spm_intent','required_entities','language','rationale_code'],
  confidence_range:[0,1],
  default_threshold:0.85,
  low_confidence_rule:'NO_IRREVERSIBLE_ACTION',
  intent_catalog:'SPM_V2_62_INTENTS'
};
const classification={spm_intent:null,secondary_spm_intent:null,confidence:0,threshold:0.85,ambiguous:true,required_entities:[],source_gate:null,risk_tier:null,sales_stage:null,language:j.language_hint,rationale_code:'WU88_NOT_IMPLEMENTED'};
return [{json:{...j,classifier_contract:contract,classification}}];

const j=$input.first().json;
const contract={
 schema:'SPM_ENTITY_OUTPUT_V1',
 record_shape:{entity:'string',raw:'any',canonical:'any',confidence:'0..1',source:'customer|system|live_source',status:'valid|needs_validation|rejected'},
 privacy:'PII must not be copied into telemetry',
 multi_student:'students[] are separate profiles; never merge grades/subjects across children',
 correction_precedence:'latest explicit customer correction wins unless a live/system source owns the field',
 critical_rules:{timezone:'never derive from country alone',booking_id:'system-only; required for booking confirmation',opt_out:'true is sticky until approved opt-in'}
};
return [{json:{...j,entity_contract:contract,entity_extraction:{entities:[],student_profiles:[],status:'WU89_NOT_IMPLEMENTED'}}}];

const j=$input.first().json;
const state=j.sales_state||{};
const contract={schema:'SPM_NEXT_BEST_ACTION_V1',stages:['none','discovery','need','consideration','pricing','trial','scheduling','conversion','objection','nurturing','support','recovery'],override_precedence:['opt_out','support','human_handoff','recovery','sales_journey'],question_policy:'ask one purposeful missing-field question; never re-ask known data'};
const decision={stage:state?.journey?.stage||'discovery',goal:'understand_customer_need',next_best_action:'understand_need',required_missing_fields:[],support_override:false,opt_out_override:Boolean(state?.nurture?.opt_out),handoff_override:Boolean(state?.support?.handoff_requested),status:'WU90_NOT_IMPLEMENTED'};
return [{json:{...j,journey_contract:contract,journey_decision:decision}}];

const j=$input.first().json;
const allowed=['APPROVED_KB_OR_LOGIC','APPROVED_CURRICULUM_SOURCE','PACKAGES_LIVE_CONFIG','AUTHORIZED_OFFER_REQUIRED','MARKET_PAYMENT_CONFIG','PAYMENT_LIVE','POLICY_AND_LIVE_STATE','VERIFIED_TEACHER_OR_POLICY','SCHEDULING_LIVE','CRM_VALIDATION'];
const gate=j.classification?.source_gate||null;
const result={gate,allowed_gates:allowed,can_answer:false,can_execute:false,source_refs:[],reason_code:gate?'WU91_SOURCE_NOT_CONNECTED':'CLASSIFICATION_NOT_READY',status:'WU91_NOT_IMPLEMENTED'};
return [{json:{...j,source_gate_contract:{schema:'SPM_SOURCE_GATE_V1',truth_rule:'commercial/operational facts require approved or live source; unsupported claims are blocked'},source_gate_result:result}}];

const j=$input.first().json;
const contract={
 schema:'SPM_SALES_AGENT_OUTPUT_V1',
 role:'consultative_sales_agent_not_faq_bot',
 fields:['answer_text','purpose','recommendation','purposeful_question','proposed_action','action_requires_gateway','claims_source_refs','handoff_requested','stop_nurture'],
 behavior:['answer_first','acknowledge_context','ask_one_purposeful_question','do_not_repeat_known_fields','no_pressure','no_unsupported_promise'],
 hard_boundary:'Agent may propose actions but cannot directly perform irreversible business actions.'
};
const output={answer_text:'WU87 architecture test reached the Sales Agent contract. The sales model is intentionally not connected yet.',purpose:'architecture_test',recommendation:null,purposeful_question:null,proposed_action:'none',action_requires_gateway:false,claims_source_refs:[],handoff_requested:false,stop_nurture:false,status:'WU92_NOT_IMPLEMENTED'};
return [{json:{...j,sales_agent_contract:contract,sales_agent_output:output}}];

const j=$input.first().json;
const requested=String(j.sales_agent_output?.proposed_action||'none');
const irreversible=['lead_upsert','booking_create','booking_change','payment_action','human_handoff_create','contact_update','opt_out_write'];
const result={requested_action:requested,executed:false,status:'NOOP_WU87',business_reference:null,reason_code:'ACTION_GATEWAY_SKELETON_ONLY',irreversible_action:false};
if (irreversible.includes(requested)) result.irreversible_action=true;
return [{json:{...j,action_gateway_contract:{schema:'SPM_ACTION_GATEWAY_V1',rule:'all irreversible actions require deterministic validation + explicit tool success before success may be reported',allowed_in_wu87:['none']},action_result:result}}];
